package com.hotelbooking.hotel_booking.service;
import com.hotelbooking.hotel_booking.dto.*; import com.hotelbooking.hotel_booking.entity.*; import com.hotelbooking.hotel_booking.exception.ApiException; import com.hotelbooking.hotel_booking.repository.*; import org.junit.jupiter.api.Test;
import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import at.favre.lib.crypto.bcrypt.BCrypt;
class SignupVerificationServiceTest {
 @Test void startStoresOnlyHashesAndDoesNotCreateUser(){UserRepository u=mock(UserRepository.class);SignupVerificationRepository v=mock(SignupVerificationRepository.class);SignupOtpDelivery d=mock(SignupOtpDelivery.class);SignupOtpConfigurationService c=config(5);when(u.existsByEmail("new@example.com")).thenReturn(false);new SignupVerificationService(u,v,d,c).start(new RegisterRequest("New",20,"NEW@example.com","Password1"));var capture=org.mockito.ArgumentCaptor.forClass(SignupVerification.class);verify(v).save(capture.capture());assertTrue(BCrypt.verifyer().verify("Password1".toCharArray(),capture.getValue().getPasswordHash()).verified);verify(d).deliver(eq("new@example.com"),eq("New"),argThat(x->x.matches("\\d{6}")),eq(5));verify(u,never()).save(any());}
 @Test void correctOtpCreatesUserAndDeletesPending(){UserRepository u=mock(UserRepository.class);SignupVerificationRepository r=mock(SignupVerificationRepository.class);SignupOtpDelivery d=mock(SignupOtpDelivery.class);SignupVerification v=new SignupVerification();v.setEmail("a@b.com");v.setName("A");v.setAge(20);v.setPasswordHash(BCrypt.withDefaults().hashToString(4,"Password1".toCharArray()));v.setOtpHash(BCrypt.withDefaults().hashToString(4,"038291".toCharArray()));v.setExpiresAt(java.time.LocalDateTime.now().plusMinutes(1));v.setAttemptCount(0);when(r.findByEmail("a@b.com")).thenReturn(Optional.of(v));when(u.existsByEmail("a@b.com")).thenReturn(false);when(u.save(any())).thenAnswer(i->i.getArgument(0));new SignupVerificationService(u,r,d,config(5)).verify(new VerifySignupRequest("a@b.com","038291"));verify(u).save(any(User.class));verify(r).delete(v);}
 @Test void wrongOtpPersistsAttempt(){UserRepository u=mock(UserRepository.class);SignupVerificationRepository r=mock(SignupVerificationRepository.class);SignupVerification v=new SignupVerification();v.setEmail("a@b.com");v.setOtpHash(BCrypt.withDefaults().hashToString(4,"123456".toCharArray()));v.setExpiresAt(java.time.LocalDateTime.now().plusMinutes(1));v.setAttemptCount(0);when(r.findByEmail("a@b.com")).thenReturn(Optional.of(v));assertThrows(ApiException.class,()->new SignupVerificationService(u,r,mock(SignupOtpDelivery.class),config(5)).verify(new VerifySignupRequest("a@b.com","000000")));assertEquals(1,v.getAttemptCount());verify(r).save(v);}
 private SignupOtpConfigurationService config(int minutes){SignupOtpConfigurationService c=mock(SignupOtpConfigurationService.class);when(c.getOtpValidity()).thenReturn(java.time.Duration.ofMinutes(minutes));return c;}
}
